import React, { useState, useRef } from "react";
import axios from "axios";
import { Button } from "@material-tailwind/react";
import { useContext } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";

function Location() {
  const [form, setForm] = useState({
 LocationCode: "",
        LocationName: "",
         address:"",
        CompanyID: "",
         isvat: "",
          isactive: "",
        username:"",
          mobileno:"",
    
  });
 const { user } = useContext(AuthContext);
  const [file, setFile] = useState(null);
  const fileInputRef = useRef(null);
const [ scat,setscat] = useState([]);
const [isOpen,setIsOpen] = useState(false);
  const [SelectedCustomer,setSelectedCustomer] = useState([]);
   const Company = async (value) => {
        
      const res = await fetch(`http://localhost:5000/Company`);
      const data = await res.json();
      setscat(data);
 
   
  }

  const handleKeyDown = (event) => {
    if(event.key === "F12"){
      event.preventDefault();
      setIsOpen(true);
      Company();
    }
  };



  // handle text input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // submit form
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
    
      

      // append image
    

      await axios.post("http://localhost:5000/location", form);


      // reset form
      setForm({
        LocationCode: "",
        LocationName: "",
        address:"",
        CompanyID: "",
         isvat: "",
          isactive: "",
        username:"",
        mobileno:"",
  
      });
alert("sucessfully");
      setFile(null);
    } catch (err) {
      console.error(err);
      alert("Error adding product");
    }

  };

  return (
   <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
     <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
      <h2 className="text-2xl font-bold mb-4 text-center">Create location</h2>
     <form onSubmit={handleSubmit} className="space-y-4">
 {user?.username ? `Welcome, ${user.username}` : "No user logged in"}
        {/* Code + Name */}
        <div className=" grid grid-cols-2 gap-4">
      
          <input
            type="text"
            name="company"
            placeholder="Company ID"
            value={form.company}
            onChange={handleChange}
             onKeyDown={handleKeyDown}
            className="w-full border p-2 rounded"
            required
          />

  
        </div>

        {/* Description + Cost */}
         <div className="grid grid-cols-2 gap-4">
       <input
            type="text"
            name="locationcode"
            placeholder="location code"
            value={form.locationcode}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
 <button className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500">New</button>
         
         </div>
          <input
            type="text"
            name="locationname"
            placeholder="location name"
            value={form.locationname}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />

         
       <input
            type="text"
            name="address"
            placeholder="address"
            value={form.address}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />

          <input
            type="text"
            name="mobileno"
            placeholder="mobile no"
            value={form.mobileno}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />



      <div className="grid grid-cols-2 gap-4">
          <label
         
          className="flex items-center gap-2 cursor-pointer"
        >
<div className="grid grid-cols-2 gap-4">

  <div>
    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="isactive"
        value="1"
        checked={form.isactive === "1"}
        onChange={handleChange}
      />
      Active
    </label>

    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="isactive"
        value="0"
        checked={form.isactive === "0"}
        onChange={handleChange}
      />
      Inactive
    </label>
  </div>

  <div>
    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="isvat"
        value="1"
        checked={form.isvat === "1"}
        onChange={handleChange}
      />
      VAT
    </label>

    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="isvat"
        value="0"
        checked={form.isvat === "0"}
        onChange={handleChange}
      />
      Non VAT
    </label>
  </div>

</div>
        </label>
  </div>


           <button
          type="submit"
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"
        >
          Save
        </button>
      </form>


 {isOpen && (
    <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          
          <div className="bg-white rounded-lg shadow-lg p-6 w-150 relative">
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          
         
            
            {/* Close Button */}
            <button
              onClick={() => setIsOpen(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

         

            {/* Content */}
     <table className="min-w-full bg-white">
  <thead className="bg-gray-100">
    <tr >
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Company Code</th>
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Company Name</th>


    </tr >
  </thead>
   <tbody className="divide-y divide-gray-200" > {scat.map((item) => 
    <tr key={item.id} className="hover:bg-gray-50" onClick={() => {setSelectedCustomer(item);setIsOpen(false);}}>
      <td className="px-6 py-4">{item.CompanyCode}</td>
      <td className="px-6 py-4">
        {item.CompanyName}
      </td>
     

    </tr>)}
    </tbody>
    </table>
   

         </div>
          <div className="flex gap-2">
            <button
 onClick={() => {
  
  setIsOpen(false);
}}
              className="mt-3 bg-red-600 hover:bg-red-700 text-white py-2 px-2 rounded-full"
            >
              Close
            </button>

        </div>           
         </div>
         </div>
        
      )}




    </div>
    </div>
  );
}

export default Location;