// Sidebar.js

import { Menu, X } from "lucide-react"; // optional icons
import { useNavigate } from "react-router-dom"; 
import React, { useState, useMemo ,useEffect } from "react";
 import { useContext } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
import { Trash2 } from "lucide-react";



const Dashboard = () => {
  const [isOpen, setIsOpen] = useState(true);
const navigate = useNavigate();
 const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
const[results,setResults]=useState([]);
const[pen,setpen]=useState([]);
 const { user } = useContext(AuthContext);
 const [oo,isoo] = useState(false);
 const[aa,setaa]=useState([]);
const [cartItemCount, setCartItemCount] = useState(0);
const [item,setitem] = useState([]);
const [selectedItem, setSelectedItem] = useState(null);
 const [sections, setSections] = useState([]);

    
 const PRODUCTSS = async (location) => {
      
      const res = await fetch(
  `http://localhost:5000/PRODUCTS?location=${location}`
);
      const data = await res.json();
      setpen(data);
 
   
  }

     
 
const handleDelete = (id) => {
  setSections((prev) => prev.filter((section) => section.id !== id));
};
  // Add item to selected pane
  const handleSelect = (item) => {
  setSections((prev) => {
    const lastSection = prev[prev.length - 1];

    // If no section OR last section already filled → create new section
    if (!lastSection || lastSection.item) {
      return [
        ...prev,
        {
          id: prev.length + 1,
          item: item,
         
        },
        
      ];

    }
     
   
    // Otherwise fill last empty section
    const updated = [...prev];
    updated[updated.length - 1] = {
      ...lastSection,
      item: item,
    };

    return updated;


  })}
  


  const CATEGORIESS = async (value) => {
  
      const res = await fetch(`http://localhost:5000/Department`);
      const data = await res.json();
      setResults(data);
    
    
     
  
    
  
  }



/*
const PRODUCTS = [
  {
    id: results.ProductCode,
    name: results.ProductName,
    category: results.CategoryID,
    price: results.SellingPrice,
    rating: 4.8,
    image: results.ProductImage,
  },
  {
    id: 2,
    name: "Smart Watch",
    category: "Electronics",
    price: 149.99,
    rating: 4.6,
    image: "https://picsum.photos/300?random=2",
  },
  {
    id: 3,
    name: "Running Shoes",
    category: "Fashion",
    price: 79.99,
    rating: 4.7,
    image: "https://picsum.photos/300?random=3",
  },
];

const CATEGORIES = [
  "All",
  "Electronics",
  "Fashion",
];*/

useEffect(() => {
  if (user?.location) {
    PRODUCTSS(user.location);
    CATEGORIESS();
  }
}, [user]);





 const filteredProducts = useMemo(() => {
  return (pen ?? []).filter((product) => {
    const matchesSearch =
      (product?.ProductName ?? "")
        .toLowerCase()
        .includes((search ?? "").toLowerCase());

    const matchesCategory =
      selectedCategory === "All" ||
      product?.Department === selectedCategory;

    return matchesSearch && matchesCategory;
  });
}, [pen, search, selectedCategory]);

  return (
    <div className="flex">
      {/* Sidebar */}
      <div
        className={`bg-slate-800 text-white h-screen p-5 pt-8 relative duration-300 ${
          isOpen ? "w-64" : "w-20"
        }`}
      >
        {/* Toggle Button */}
        <button
          className="absolute -right-3 top-9 bg-white text-black rounded-full p-1"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X size={18} /> : <Menu size={18} />}
        </button>

        {/* Logo */}
        <h1 className={`text-2xl font-bold mb-6 ${!isOpen && "hidden"}`}>
          MPOS
        </h1>

        {/* Menu */}
        <ul className="space-y-4">
         <li className="hover:bg-slate-700 p-2 rounded cursor-pointer" onClick={() => navigate("/home")}>
          Home
          </li>
          <li className="hover:bg-slate-700 p-2 rounded cursor-pointer" onClick={() => {navigate("/Dashboard");}}>
         Catelog

          </li>

          <li className="hover:bg-slate-700 p-2 rounded cursor-pointer" onClick={() => navigate("/Settingss")}>
            Settings
          </li>
          <li className="hover:bg-slate-700 p-2 rounded cursor-pointer" >
            Logout
          </li>
        </ul>
      </div>

      {/* Main Content */}
    

 <div className="min-h-screen bg-gray-100">
      {/* Header */}
      <header className="bg-indigo-600 text-white shadow-md">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <h1 className="text-2xl font-bold">Product Catalogue</h1>

          <input
            type="text"
            placeholder="Search products..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-72 px-4 py-2 rounded-lg text-black outline-none"
          />

          <button type="button" className="relative p-2 text-gray-600 hover:text-indigo-600 hover:bg-gray-50 rounded-full transition-all focus:outline-none" onClick={() => {isoo(true);}}
          aria-label="Shopping Cart">
            <svg xmlns="http://w3.org" fill="none" viewBox="0 0 24 24" strokeWidth="2" stroke="currentColor" className="w-6 h-6">
           <path
  strokeLinecap="round"
  strokeLinejoin="round"
  d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-1 5h12m-9 0a1 1 0 100 2 1 1 0 000-2zm8 0a1 1 0 100 2 1 1 0 000-2"
/>
            </svg>
            {cartItemCount > 0 && ( 
              <span className="absolute top-0 right-0 transform translate-x-1/2 -translate-y-1/3 min-w-5 h-5 bg-red-500 text-white text-xs font-bold rounded-full flex items-center justify-center px-1 animate-fade-in shadow-sm">
                {cartItemCount}
              </span>
            )}
          </button>
        </div>
      </header>

      {/* Main Content */}
      <div className="max-w-7xl mx-auto flex flex-col md:flex-row gap-6 p-6">
        {/* Sidebar */}
        <aside className="w-full md:w-64 bg-white rounded-xl shadow-md p-5">
          <h2 className="text-lg font-semibold mb-4">Supplier</h2>

          <div className="space-y-2">
            {results.map((Supplier) => (
              <button
                key={Supplier.DepartmentCode}
                onClick={() => setSelectedCategory(Supplier.DepartmentName)}
                className={`w-full text-left px-4 py-2 rounded-lg transition ${
                  selectedCategory === Supplier.DepartmentName
                    ? "bg-indigo-600 text-white"
                    : "bg-gray-100 hover:bg-gray-200"
                }`}
              >
                {Supplier.DepartmentName}
              </button>
            ))}
          </div>
        </aside>

        {/* Products */}
        <main className="flex-1"> 
          <p className="mb-4 text-gray-600">
          "
            Showing {pen.length} products
          </p>

          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredProducts.map((product) => (
              <div
                key={product.id}
                className="bg-white rounded-xl shadow-md overflow-hidden hover:shadow-xl transition"
              >
                <img
                  src={product.ProductImage}
                  alt={product.ProductName}
                  className="w-full h-56 object-cover"
                />

                <div className="p-4">
                  <span className="text-xs bg-indigo-100 text-indigo-600 px-2 py-1 rounded">
                    {product.Department}
                  </span>

                  <h3 className="mt-3 text-lg font-semibold">
                    {product.ProductName}
                  </h3>


                

                  <div className="flex justify-between items-center mt-4">
                    <span className="text-xl font-bold text-indigo-600">
                      {product.SellingPrice}
                    </span>

                    <button className="bg-indigo-600 hover:bg-indigo-700 text-white px-4 py-2 rounded-lg" onClick={() => {
    setSelectedItem(product);
    handleSelect(product);
}}>
                      Add Cart
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {results.length === 0 && (
            <div className="bg-white p-10 rounded-xl shadow text-center">
              <p className="text-gray-500">
                No products found matching your search.
              </p>
            </div>
          )}
        </main>

  {oo && (
        <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          
          <div className="bg-white rounded-lg shadow-lg p-6 w-96 relative">
            
            {/* Close Button */}
            <button
              onClick={() => isoo(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

            {/* Content */}
           
 <ul className="divide-y">
    <li          
       className="grid grid-cols-[2fr_1fr_1fr_1fr_0.5fr] gap-2 px-2 py-2 bg-gray-100 border-b text-xs font-semibold text-gray-600"
          >
             <span className="text-sm font-medium">
              ProductCode
            </span>
            <span className="text-sm font-medium">
              Product
            </span>
             <span className="text-sm font-medium">
              Discount
            </span>
              <span className="text-sm font-medium">
              Qty
            </span>
              <span className="text-sm font-medium">
              Price
            </span>
          </li>
 </ul>

  {sections.length === 0 ? (
      <p className="text-gray-400 text-center mt-10">
        No items added
      </p>
    ) : (
      <ul className="divide-y">
        {sections.map((section) => (
          <li
            key={section.id}
            className="flex justify-between items-center py-3 px-2 hover:bg-gray-100"
          >
             <span className="text-sm font-medium">
              {section.item.ProductCode }
            </span>

            <span className="text-sm font-medium">
              {section.item.ProductName }
            </span>

              <span className="text-sm font-medium">
              {section.item.FixedDiscountPercentage + '%'}
            </span>

             <span className="text-sm font-medium">
              {item.qty}
            </span>

            <span className="text-sm font-medium">
              {section.item.SellingPrice}
            </span>

            <Trash2
              size={18}
              className="text-red-500 cursor-pointer hover:text-red-700"
              onClick={() => handleDelete(section.id)}
            />
          </li>
        ))}
      </ul>
    )}



    


    
 

            <button
 onClick={() => {

  isoo(false);
}}
              className="px-4 py-2 bg-red-500 text-white rounded"
            >
              Add
            </button>

         </div>
        </div> 
      )}



      </div>
    </div>
    </div>
  );
}




export default Dashboard;