import React, { useState, useRef } from "react";
import axios from "axios";
import { useContext } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
function Supplier() {
  const [form, setForm] = useState({
        code: "",
        suppliername: "",
        Gender: "",
        address: "",
        mobileno: "",
        email: "",
        contactperson: "",
        paymentMethod: "",
        creditlimit: "",
        CreditPeriod: "",
        chequelimit: "",
        ChequePeriod: "",
        Currancytype: "",
        username:"",
  });
    const { user } = useContext(AuthContext);
  const [file, setFile] = useState(null);
  const fileInputRef = useRef(null);
 const [activeIndex, setActiveIndex] = useState(""); 
     const [results, setResults] = useState([]); 
      const handleSearchs = async (value) => {
   
      const res = await fetch(`http://localhost:5000/suppliercode?q=${value}`);
      const data = await res.json();
    
    if (data.length > 0) {
      const lastCode =  data[0].SupplierCode; // e.g. D001
alert(lastCode)
      // remove letters → get number part
      const numberPart = parseInt(lastCode.replace(/\D/g, ""), 10);

      // +1
      const nextNumber = numberPart +1;

      // format back with leading zeros
      const nextCode = "S"+`${String(nextNumber).padStart(4, "0")}`;

      setForm((prev) => ({
        ...prev,
        code: nextCode,
      }));
    }
    setActiveIndex(0);   
   
    
    
  };

  // handle text input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // submit form
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const formData = new FormData();

      // append all text fields
    

      await axios.post("http://localhost:5000/supplier", formData)

      alert("Product added!");

      // reset form
      setForm({
        code: "",
        suppliername: "",
        Gender: "",
        address: "",
        mobileno: "",
        email: "",
        contactperson: "",
        paymentMethod: "",
        creditlimit: "",
        CreditPeriod: "",
        chequelimit: "",
        ChequePeriod: "",
        Currancytype: "",
        username:"",
        
      });

      setFile(null);
    } catch (err) {
      console.error(err);
      alert("Error adding product");
    }



  };

  return (
   <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
     <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
      <h2 className="text-2xl font-bold mb-4 text-center">Create Supplier</h2>
 {user?.username ? `Welcome, ${user.username}` : "No user logged in"}
      <form onSubmit={handleSubmit} className="space-y-4">

        {/* Code + Name */}
        <div className="grid grid-cols-2 gap-4">
      
          <input
            type="text"
            name="code"
            placeholder="Supplier Code"
            value={form.code}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
<button type="button" className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500" onClick={handleSearchs}>New</button>
       </div>
       <div className="grid grid-cols-2 gap-4">
          <input
            type="text"
            name="suppliername"
            placeholder="Supplier Name"
            value={form.suppliername}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
       

    
          <select
  name="Gender"
  value={form.Gender}
  onChange={handleChange}
  className="w-full border p-2 rounded"
  required
>  <option value="">Gender</option>
  <option value="1">Male</option>

  <option value="2">Female</option>
</select>
  </div>  
     <div className="grid grid-cols-2 gap-4">  
          <input
            type="text"
            name="address"
            placeholder="Address"
            value={form.address}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
      

      
          <input
            type="number"
            name="mobileno"
            placeholder="Mobile No"
            value={form.mobileno}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>
 <div className="grid grid-cols-2 gap-4">
          <input
            type="text"
            name="email"
            placeholder="Email"
            value={form.email}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
       
        
          <input
            type="text"
            name="contactperson"
            placeholder="Contact Person"
            value={form.contactperson}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>
 <div className="grid grid-cols-2 gap-4">
        <select
  name="paymentMethod"
  value={form.paymentMethod}
  onChange={handleChange}
  className="w-full border p-2 rounded"
  required
>  <option value="">Payment Method</option>
  <option value="1">Cash</option>

  <option value="2">Credit</option>
</select>
       
        
          <input
            type="number"
            name="creditlimit"
            placeholder="Credit limit"
            value={form.creditlimit}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
          </div>
<div className="grid grid-cols-2 gap-4">
           <select
  name="CreditPeriod"
  value={form.CreditPeriod}
  onChange={handleChange}
  className="w-full border p-2 rounded"
  required
>  <option value="">CreditPeriod</option>
  <option value="45">45</option>

  <option value="90">90</option>
</select>
       
         
          <input
            type="text"
            name="chequelimit"
            placeholder="Cheque limit"
            value={form.chequelimit}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
 </div>
 <div className="grid grid-cols-2 gap-4">
         <select
  name="ChequePeriod"
  value={form.ChequePeriod}
  onChange={handleChange}
  className="w-full border p-2 rounded"
  required
>  <option value="">ChequePeriod</option>
  <option value="45">45</option>

  <option value="90">90</option>
</select>
        
 
              <select
  name="Currancytype"
  value={form.Currancytype}
  onChange={handleChange}
  className="w-full border p-2 rounded"
  required
>  <option value="">Currancytype</option>
  <option value="LKR">LKR</option>

  <option value="USD">USD</option>
</select>
          

       
        </div>
          {/* Image preview */}
        {file && (
          <img
            src={URL.createObjectURL(file)}
            alt="preview"
            className="w-32 h-32 object-cover rounded"
          />
        )}

        {/* File upload */}
        <div className="space-y-2">
          <input
            type="file"
            ref={fileInputRef}
            onChange={(e) => setFile(e.target.files[0])}
            className="hidden"
          />

          <button
            type="button"
            onClick={() => fileInputRef.current.click()}
            className="bg-gray-200 px-4 py-2 rounded hover:bg-gray-300"
          >
            Choose Image
          </button>

          {file && (
            <p className="text-sm text-gray-600">{file.name}</p>
          )}
        </div>
  <button
          type="submit"
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"
        >
          Save Supplier
        </button>
      </form>
    </div>
    </div>
  );
}

export default Supplier;