import React, { useState } from "react";
import './index.css';
import { useContext } from "react";
import { AuthContext } from "./pos/SERVER/AuthContext.js";

import { useNavigate } from "react-router-dom";

 
function Homes() {

 const navigate = useNavigate();
 const { user } = useContext(AuthContext);

  return (
    
    <div className="h-screen flex items-center justify-center bg-[#e0e5ec]">
      <div className="flex gap-6">
        {user?.username ? `Welcome, ${user.username}` : "No user logged in"}
        <button className="px-10 py-5 text-xl font-semibold rounded-2xl 
          bg-blue-500 text-white
          shadow-xl shadow-blue-300/50
          hover:scale-110 hover:shadow-blue-400/70
          active:scale-95 active:shadow-inner
          transition-all duration-200" onClick={() => navigate("/sidebar")}>
          POS
        </button>

        <button className="px-10 py-5 text-xl font-semibold rounded-2xl 
          bg-green-500 text-white
          shadow-xl shadow-green-300/50
          hover:scale-110 hover:shadow-green-400/70
          active:scale-95 active:shadow-inner
          transition-all duration-200" onClick={() => navigate("/ERP")} >
          ERP
        </button>

        <button className="px-10 py-5 text-xl font-semibold rounded-2xl 
          bg-purple-500 text-white
          shadow-xl shadow-purple-300/50
          hover:scale-110 hover:shadow-purple-400/70
          active:scale-95 active:shadow-inner
          transition-all duration-200">
          ADMIN
        </button>


      </div>
   
    </div>
   
    
   
  );
}


export default Homes;