import React, { useState, useRef } from "react";
import axios from "axios";
import { useContext } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
function Salesperson() {
  const [form, setForm] = useState({
    code: "",
        Salespersonname: "",
        mobileno: "",
        address: "",
        creditlimit: "",
        discountlimit: "",
  });
 const { user } = useContext(AuthContext);
  const [file, setFile] = useState(null);
  const fileInputRef = useRef(null);
 const [activeIndex, setActiveIndex] = useState(""); 
     const [results, setResults] = useState([]); 
      const handleSearchs = async (value) => {
   
      const res = await fetch(`http://localhost:5000/salespersoncode?q=${value}`);
      const data = await res.json();
    
    if (data.length > 0) {
      const lastCode =  data[0].SalesPersonCode; // e.g. D001

      // remove letters → get number part
      const numberPart = parseInt(lastCode.replace(/\D/g, ""), 10);

      // +1
      const nextNumber = numberPart +1;

      // format back with leading zeros
      const nextCode = "S"+`${String(nextNumber).padStart(4, "0")}`;

      setForm((prev) => ({
        ...prev,
        code: nextCode,
      }));
    }
    setActiveIndex(0);   
   
    
    
  };

  // handle text input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // submit form
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const formData = new FormData();

      // append all text fields
      Object.keys(form).forEach((key) => {
        formData.append(key, form[key]);
      });

      // append image
      if (file) {
        formData.append("image", file);
      }

      await axios.post("http://localhost:5000/salesperson", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      alert("Product added!");

      // reset form
      setForm({
        code: "",
        Salespersonname: "",
        mobileno: "",
        address: "",
        creditlimit: "",
        discountlimit: "",
       username:"",
      });

      setFile(null);
    } catch (err) {
      console.error(err);
      alert("Error adding product");
    }
  };

  return (
   <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
     <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
      <h2 className="text-2xl font-bold mb-4 text-center">Create Salesperson</h2>
 {user?.username ? `Welcome, ${user.username}` : "No user logged in"}
      <form onSubmit={handleSubmit} className="space-y-4">

        {/* Code + Name */}
        <div className="grid grid-cols-2 gap-4">
      
          <input
            type="text"
            name="code"
            placeholder="Product Code"
            value={form.code}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
         
          <button type="button" className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500" onClick={handleSearchs}>New</button>
        </div>
        <div className="grid grid-cols-2 gap-4">
          <input
            type="text"
            name="Salespersonname"
            placeholder="Product Name"
            value={form.Salespersonname}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        

        {/* Description + Cost */}
       
          <input
            type="text"
            name="mobileno"
            placeholder="mobileno"
            value={form.mobileno}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>
 <div className="grid grid-cols-2 gap-4">
          <input
            type="text"
            name="address"
            placeholder="address"
            value={form.address}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
       

        {/* Selling + Discount */}
      
          <input
            type="number"
            name="creditlimit"
            placeholder="creditlimit"
            value={form.creditlimit}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
          </div>
 <div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="discountlimit"
            placeholder="discountlimit"
            value={form.discountlimit}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        </div>

        {/* Image preview */}
        {file && (
          <img
            src={URL.createObjectURL(file)}
            alt="preview"
            className="w-32 h-32 object-cover rounded"
          />
        )}

        {/* File upload */}
        <div className="space-y-2">
          <input
            type="file"
            ref={fileInputRef}
            onChange={(e) => setFile(e.target.files[0])}
            className="hidden"
          />

          <button
            type="button"
            onClick={() => fileInputRef.current.click()}
            className="bg-gray-200 px-4 py-2 rounded hover:bg-gray-300"
          >
            Choose Image
          </button>

          {file && (
            <p className="text-sm text-gray-600">{file.name}</p>
          )}
        </div>

        {/* Submit */}
        <button
          type="submit"
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"
        >
          Save Product
        </button>
      </form>
    </div>
    </div>
  );
}

export default Salesperson;