const retrievetog = async (INV) => {
  try {

  

      const res = await axios.get(
      `http://localhost:5000/pendinginvdet?q=${INV}`
    );

    const details = res.data;

    const restoredSections = details.map((item) => ({
      
      id: crypto.randomUUID(),

      item: {
        ProductCode: item.productcode,
        ProductName: item.productname,
       SellingPrice: Number(item.sellingprice || item.SellingPrice || 0),
        FixedDiscountPercentage: Number(
          item.fixeddiscountpercentage,    
        ),
              qty: item.qty,
      },

  
    }));

    // ADD ITEMS TO CART
   setSections((prev) => {
  const updated = [...prev];

  restoredSections.forEach((newItem) => {
    const existing = updated.find(
      (x) =>
        x.item.ProductCode ===
        newItem.item.ProductCode
    );

    if (existing) {
      existing.qty += newItem.qty;
    } else {
    
      updated.push(newItem);
    }
  });

  return updated;
  
});
    

    // RESTORE HEADER
    setSavepo((prev) => ({
      ...prev,
  
    }));

    setIsOpen(false);

  } catch (err) {
    console.error(err);
    alert("Error retrieving PO");
  }
};

