import React, { useState, useRef } from "react";
import axios from "axios";
import { useContext } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
import { useNavigate } from "react-router-dom";
function Logout() {
    const { user } = useContext(AuthContext);
const navigate = useNavigate();
const out = () => {

  localStorage.removeItem("token");
  localStorage.removeItem("user");
  sessionStorage.clear();
  navigate("/");

}


  return (
   <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
     <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
       {user?.username ? `Welcome, ${user.username}` : "No user logged in"}
      <h2 className="text-2xl font-bold mb-4 text-center">Logout</h2>

  
<p>Confirm logout to end your current session. For your security, you will need to sign in again to access your account.</p>
    

       <div className="grid grid-cols-2 gap-4">
           <button
          type="submit"
          className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"  onClick={() => out()}
        >
          Yes
        </button>

             <button
          type="submit"
          className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"
        >
          No
        </button>
       </div>
   
    </div>
    </div>
  );
}

export default Logout;