import React, { useState, useRef } from "react";
import axios from "axios";
import { useContext } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
function Catagory() {
  const [form, setForm] = useState({
    categorycode: "",
    categoryname: "",
    Remark: "",
    username:"",
   
  });
 const { user } = useContext(AuthContext); 
  const [file, setFile] = useState(null);
  const fileInputRef = useRef(null);
   const [activeIndex, setActiveIndex] = useState(""); 
   const [results, setResults] = useState([]); 
      const handleSearchs = async (value) => {
   
      const res = await fetch(`http://localhost:5000/categorycode?q=${value}`);
      const data = await res.json();
    
    if (data.length > 0) {
      const lastCode =  data[0].CategoryCode || data[0].categorycode; // e.g. D001

      // remove letters → get number part
      const numberPart = parseInt(lastCode.replace(/\D/g, ""), 10);

      // +1
      const nextNumber = numberPart + 1;

      // format back with leading zeros
      const nextCode = `${String(nextNumber).padStart(3, "0")}`;

      setForm((prev) => ({
        ...prev,
        categorycode: nextCode,
      }));
    }
    setActiveIndex(0);   
   
    
    
  };

  // handle text input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // submit form
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
   


      await axios.post("http://localhost:5000/category", form);

      alert("Product added!");

      // reset form
      setForm({
       categorycode: "",
    categoryname: "",
    Remark: "",
    username:"",
      });

      setFile(null);
    } catch (err) {
      console.error(err);
      alert("Error adding product");
    }
  };

  return (
   <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
     <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
      <h2 className="text-2xl font-bold mb-4 text-center">Create Catagory</h2>

      <form onSubmit={handleSubmit} className="space-y-4">

        {/* Code + Name */}
         <div className="grid grid-cols-2 gap-4">
      
          <input
            type="text"
            name="categorycode"
            placeholder="categorycode"
            value={form.categorycode}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />

   <button type="button" className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500" onClick={handleSearchs}>New</button>
        </div>

        {/* Description + Cost */}
        
       <input
            type="text"
            name="categoryname"
            placeholder="categoryname"
            value={form.categoryname}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />

          <input
            type="text"
            name="Remark"
            placeholder="Remark"
            value={form.Remark}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
 {user?.username ? `Welcome, ${user.username}` : "No user logged in"}
      
           <button
          type="submit"
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"
        >
          Save
        </button>
      </form>
    </div>
    </div>
  );
}

export default Catagory;