import React, { useState, useRef,useEffect } from "react";
import axios from "axios";
 import { useContext } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";
import * as XLSX from "xlsx";

function CreateProduct() {
  const [isOpen,setIsOpen] = useState(false);
const [activeIndex, setActiveIndex] = useState(0);
    const [sections, setSections] = useState([]);
   const [isOpenn,setIsOpenn] = useState(false);
    const [isOpennn,setIsOpennn] = useState(false);
        const [isOpennnn,setIsOpennnn] = useState(false);
  const [SelectedCustomer,setSelectedCustomer] = useState([]);
   const [SelectedCustomers,setSelectedCustomers] = useState([]);
    const [SelectedCustomerss,setSelectedCustomerss] = useState([]);
      const [SelectedCustomersss,setSelectedCustomersss] = useState([]);
     
  const [results,setResults]= useState([]);
  const [resultss,setResultss]= useState([]);
  const [resultsss,setResultsss]= useState([]);
    const [resultssss,setResultssss]= useState([]);
      const [openDropdown, setOpenDropdown] = useState(false);
      
const [data, setData] = useState([]);
     const [query, setQuery] = useState("");
  const[tx,istx]=useState(0);
  const [act,isact]=useState(0);
  const [sup,setsup] = useState([]);
  const [depp,setdepp] = useState([]);
   const [cat,setcat] = useState([]);
     const [scat,setscat] = useState([]); 
      const { user } = useContext(AuthContext);
      const [qty, setQty] = useState(0);
      const [selectedItem, setSelectedItem] = useState(null);
  const [form, setForm] = useState({
    code: "",
    productname: "",
    Description: "",
    Costprice: "",
    Sellingprice: "",
    Discountprice: "",
    Maximumprice: "",
    Minimumprice: "",
    discountPercentage: "",
    dollarprice: "",
    Department: "",
    Category: "",
    SubCategory: "",
    WholesalePrice: "",
     isactive: "",
        istax: "",
          reorderlevel:"",
        reorderqty:"",
        supplier:"",
  });


  const handleSearch = async (locationID,value) => {
       
      const res = await fetch(`http://localhost:5000/search?LocationID=${locationID}&q=${value}`);
      const data = await res.json();
      setResults(data);
    
    
   
  
  }

 const handleSelect = (item) => {
  setSections((prev) => {
    const lastSection = prev[prev.length - 1];

    // If no section OR last section already filled → create new section
    if (!lastSection || lastSection.item) {
      return [
        ...prev,
        {
          id: prev.length + 1,
          item: item,
          qty: Number(qty),
        },
        
      ];

    }})}
 const handleFileUpload = (e) => {
    const file = e.target.files[0];

    if (!file) return;

    const reader = new FileReader();

    reader.onload = async (event) => {
      const binaryStr = event.target.result;
 const workbook = XLSX.read(binaryStr, {
        type: "binary",
      });

      // Get first sheet
      const sheetName = workbook.SheetNames[0];
      const worksheet = workbook.Sheets[sheetName];

      // Convert sheet to JSON
   const data = XLSX.utils.sheet_to_json(worksheet);

      try {
        await axios.post("http://localhost:5000/api/import", data);

        alert("Data imported successfully.");
       } catch (err) {
  console.error(err);

  if (err.response) {
    console.log(err.response.data);
    alert(err.response.data);
  } else {
    alert(err.message);
  }
}
    
    };

    reader.readAsBinaryString(file);
  };


 const Supplier = async (value) => {
        
      const res = await fetch(`http://localhost:5000/Supplier`);
      const data = await res.json();
      setsup(data);
 
   
  }
 const Department = async () => {
        
      const res = await fetch(`http://localhost:5000/Department`);
      const data = await res.json();
      setdepp(data);
 
   
  }


 const Category = async (value) => {
        
      const res = await fetch(`http://localhost:5000/Category`);
      const data = await res.json();
      setcat(data);
 
   
  }

   const SubCatagory = async (value) => {
        
      const res = await fetch(`http://localhost:5000/SubCategory`);
      const data = await res.json();
      setscat(data);
 
   
  }




  const handleKeyDown = (event) => {
    if(event.key === "F12"){
      event.preventDefault();
      setIsOpen(true);
      Department();
    }
  };

 const handleKeyDownc = (event) => {
    if(event.key === "F12"){
      event.preventDefault();
      setIsOpenn(true);
      Category();
    }
  };


  const handleKeyDownsc = (event) => {
    if(event.key === "F12"){
      event.preventDefault();
      setIsOpennn(true);
      SubCatagory();
    }
  };

  const handleKeyDownsup = (event) => {
    if(event.key === "F12"){
      event.preventDefault();
      setIsOpennnn(true);
      Supplier();
    }
  };


    const handleKeyDowncode = (event) => {
    if(event.key === "Enter"){
      event.preventDefault();
      pcode(user.location, form.code);
    }
  };

useEffect(() => {


  const handleClickOutside = () => {
    setOpenDropdown(false);
  };

  const handleKeyDown = (e) => {

    if (openDropdown) {

      if (e.key === "ArrowDown") {
        e.preventDefault();

        setActiveIndex((prev) =>
          prev < results.length - 1 ? prev + 1 : 0
        );
      }

      if (e.key === "ArrowUp") {
        e.preventDefault();

        setActiveIndex((prev) =>
          prev > 0 ? prev - 1 : results.length - 1
        );
      }

      if (e.key === "Enter") {
        e.preventDefault();

        if (results[activeIndex]) {
          handleSelect(results[activeIndex]);
        }

      }

      if (e.key === "Escape") {
        setOpenDropdown(false);
      }
    }
  };

  document.addEventListener("click", handleClickOutside);

  window.addEventListener("keydown", handleKeyDown);

  return () => {
    document.removeEventListener(
      "click",
      handleClickOutside
    );

    window.removeEventListener(
      "keydown",
      handleKeyDown
    );
  };

}, [
  openDropdown,
  results,
  activeIndex
]);


  const dep = async (value) => {
        if (value.length > 2) {
      const res = await fetch(`http://localhost:5000/recallpo?q=${value}`);
      const data = await res.json();
      setResults(data);
        }};
  const [file, setFile] = useState(null);
  const fileInputRef = useRef(null);

  // handle text input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // submit form
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      const formData = new FormData();

      // append all text fields
      Object.keys(form).forEach((key) => {
        formData.append(key, form[key]);
      });

      // append image
      if (file) {
        formData.append("image", file);
      }

      await axios.post("http://localhost:5000/api/products", formData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      });

      alert("Product added!");

      // reset form
      setForm({
        code: "",
        productname: "",
        Description: "",
        Costprice: "",
        Sellingprice: "",
        Discountprice: "",
        Maximumprice: "",
        Minimumprice: "",
        discountPercentage: "",
        dollarprice: "",
        Department: "",
        Category: "",
        SubCategory: "",
        WholesalePrice: "",
        isactive: "",
        istax: "",
        reorderlevel:"",
        reorderqty:"",
        supplier:"",
      });

      setFile(null);
    } catch (err) {
      console.error(err);
      alert("Error adding product");
    }
  

  };


  const pcode = async (locationID,value) => {
    const res = await fetch(`http://localhost:5000/pcode?LocationID=${locationID}&q=${value}`);
     
      const data = await res.json();
    


if (data.length > 0) {
  const item = data[0];
loadProduct(item);

  
  }
  }



const loadProduct = (item) => {
    setForm({
        code: item.ProductCode || "",
        productname: item.ProductName || "",
        Description: item.Description || "",
        Costprice: item.CostPrice || 0,
        Sellingprice: item.SellingPrice || 0,
        Discountprice: item.FixedDiscount || 0,
        Maximumprice: item.MaximumPrice || 0,
        Minimumprice: item.MinimumPrice || 0,
        discountPercentage: item.FixedDiscountPercentage || 0,
        dollarprice: item.DollarPrice || 0,
        Department: item.Department || "",
        Category: item.Category || "",
        SubCategory: item.SubCategory || "",
        WholesalePrice: item.WholesalePrice || 0,
        isactive: String(item.isactive ?? ""),
        istax: String(item.istax ?? ""),
        reorderlevel: item.ReOrderLevel || 0,
        reorderqty: item.ReOrderQty || 0,
        supplier: item.Supplier || "",
    });

    setSelectedCustomer({ DepartmentName: item.Department });
    setSelectedCustomersss({ CategoryName: item.Category });
    setSelectedCustomers({ SubCategoryName: item.SubCategory });
    setSelectedCustomerss({ SupplierName: item.Supplier });
};






  const code = async (value) => {
   
      const res = await fetch(`http://localhost:5000/productcode?q=${value}`);
      const data = await res.json();
    
    if (data.length > 0) {
      const lastCode =  data[0].productcode || data[0].productcode; // e.g. D001

      // remove letters → get number part
      const numberPart = parseInt(lastCode.replace(/\D/g, ""), 10);

      // +1
      const nextNumber = numberPart + 1;

      // format back with leading zeros
      const nextCode = `${String(nextNumber).padStart(3, "0")}`;

      setForm((prev) => ({
        ...prev,
        code: nextCode,
      }));
    }
   
   
    
    
  };

  return (
   <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
     <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
      <h2 className="text-2xl font-bold mb-4 text-center">Product Master</h2>


  <div>
      {/* Hidden file input */}
      <input
        type="file"
        id="excelFile"
        accept=".xlsx,.xls"
        style={{ display: "none" }}
        onChange={handleFileUpload}
      />

      {/* Import Button */}
      <button onClick={() => document.getElementById("excelFile").click()}>
        Import Excel
      </button>

       {/* Display imported data */}
      {data.length > 0 && (
        <table border="1" cellPadding="8" style={{ marginTop: "20px" }}>
          <thead>
            <tr>
              {Object.keys(data[0]).map((key) => (
                <th key={key}>{key}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {data.map((row, index) => (
              <tr key={index}>
                {Object.values(row).map((value, i) => (
                   <td key={i}>{String(value)}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>


            <input
          type="search"
           className="w-80 px-5 py-3 rounded-full bg-white shadow-md border border-gray-200
      focus:outline-none focus:ring-2 focus:ring-blue-500"
          value={query}
        onChange={(e) =>{ const value = e.target.value; setQuery(value); 
           if (!value.trim()) {
    setResults([]);
    setOpenDropdown(false);
    return;
  }    setOpenDropdown(true);handleSearch(user.location,value);
        }}
          placeholder="Product Search" />

      
 <ul role="list" className="p-6 divide-y divide-slate-200">  {results.map((item) => (
 
  
    <li key={item.id} class="flex py-4 first:pt-0 last:pb-0  hover:bg-slate-100" onClick={() => {
  setSelectedItem(item);
  setQty(1);
loadProduct(item);

  setSelectedCustomer({
    DepartmentName: item.Department,
  });

  setSelectedCustomersss({
    CategoryName: item.Category,
  });

  setSelectedCustomers({
    SubCategoryName: item.SubCategory,
  });

  setSelectedCustomerss({
    SupplierName: item.Supplier,
  });

 // reset default qty
 
}}>
      <img className="h-10 w-10 rounded-full" src="{item.imageUrl}" alt="" />
      <div className="ml-3 overflow-hidden">
        <p className="text-sm font-medium text-slate-900">{item.ProductName}</p>
        <p className="text-sm text-slate-500 truncate">{item.ProductCode}</p>
          <p className="text-sm text-slate-500 truncate">{item.SellingPrice}</p>
            <p className="text-sm text-slate-500 truncate">{item.Stock}</p>
      </div>
    </li>))}
 
</ul>

      <form onSubmit={handleSubmit} className="space-y-4">  

        {/* Code + Name */}
        <div className="grid grid-cols-2 gap-4">
      
          <input
            type="text"
            name="code"
            placeholder="Product Code"
            value={form.code}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
             onKeyDown={handleKeyDowncode}
          />

   <button type="button" className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500" onClick={code}>New</button>
</div>
      <div className="grid grid-cols-2 gap-4">
          <input
            type="text"
            name="productname"
            placeholder="Product Name"
            value={form.productname}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        

  
          <input
            type="text"
            name="Description"
            placeholder="Description"
            value={form.Description}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>
      <div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="Costprice"
            placeholder="Cost Price"
            value={form.Costprice}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        

        {/* Selling + Discount */}
  
          <input
            type="number"
            name="Sellingprice"
            placeholder="Selling Price"
            value={form.Sellingprice}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>
      <div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="Discountprice"
            placeholder="Discount Price"
            value={form.Discountprice}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        

          <input
            type="number"
            name="Maximumprice"
            placeholder="Maximum Price"
            value={form.Maximumprice}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>
      <div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="Minimumprice"
            placeholder="Minimum Price"
            value={form.Minimumprice}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        

        {/* Discount + Retail */}
      
          <input
            type="number"
            name="discountPercentage"
            placeholder="Discount %"
            value={form.discountPercentage}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>


<div className="grid grid-cols-2 gap-4">
          <input
            type="text"
            name="supplier"
            placeholder="Supplier"
            value={SelectedCustomerss.SupplierName}
            onChange={handleChange}
              onKeyDown={handleKeyDownsup}
             

            className="w-full border p-2 rounded"
            required
          />
        

     
          <input
            type="text"
            name="WholesalePrice"
            placeholder="Wholesale Price"
            value={form.WholesalePrice}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        
</div>




      <div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="dollarprice"
            placeholder="Dollar Price"
            value={form.dollarprice}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
  





          <input
            type="text"
            name="Department"
            placeholder="Department"
            value={SelectedCustomer.DepartmentName}
            onChange={handleChange}
            onKeyDown={handleKeyDown}
           
            className="w-full border p-2 rounded"
            required
            
          />
          
</div>
      <div className="grid grid-cols-2 gap-4">
          <input
            type="text"
            name="Category"
            placeholder="Category"
            value={SelectedCustomersss.CategoryName}
            onChange={handleChange}
             onKeyDown={handleKeyDownc}
 
            className="w-full border p-2 rounded"
            required
          />
        

     
          <input
            type="text"
            name="SubCategory"
            placeholder="Sub Category"
            value={SelectedCustomers.SubCategoryName}
            onChange={handleChange}
             onKeyDown={handleKeyDownsc}
            
            className="w-full border p-2 rounded"
            required
          />
</div>

<div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="reorderlevel"
            placeholder="REORDER LEVEL"
            value={form.reorderlevel}
            onChange={handleChange}
            
            className="w-full border p-2 rounded"
            required
          />
        

     
          <input
            type="number"
            name="reorderqty"
            placeholder="REORDER QUENTITY"
            value={form.reorderqty}
            onChange={handleChange}
        
            className="w-full border p-2 rounded"
            required
          />
</div>


      <div className="grid grid-cols-2 gap-4">
          <label
         
          className="flex items-center gap-2 cursor-pointer"
        >
<div className="grid grid-cols-2 gap-4">

  <div>
    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="isactive"
        value="1"
        checked={form.isactive === "1"}
        onChange={handleChange}
      />
      Active
    </label>

    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="isactive"
        value="0"
        checked={form.isactive === "0"}
        onChange={handleChange}
      />
      Inactive
    </label>
  </div>

  <div>
    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="istax"
        value="1"
        checked={form.istax === "1"}
        onChange={handleChange}
      />
      Taxable
    </label>

    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="istax"
        value="0"
        checked={form.istax === "0"}
        onChange={handleChange}
      />
      Non Taxable
    </label>
  </div>

</div>
        </label>
  
        


        {/* Image preview */}
        {file && (
          <img
            src={URL.createObjectURL(file)}
            alt="preview"
            className="w-32 h-32 object-cover rounded"
          />
        )}

        {/* File upload */}
        <div className="space-y-2">
          <input
            type="file"
            ref={fileInputRef}
            onChange={(e) => setFile(e.target.files[0])}
            className="hidden"
          />

          <button
            type="button"
            onClick={() => fileInputRef.current.click()}
            className="bg-gray-200 px-4 py-2 rounded hover:bg-gray-300"
          >
            Choose Image
          </button>

          {file && (
            <p className="text-sm text-gray-600">{file.name}</p>
          )}
        </div>

        {/* Submit */}
        <button
          type="submit"
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"
        >
          Save Product
        </button>
        </div>
      </form>
      
 {/* customers details*/} 
  {isOpen && (
    <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          
          <div className="bg-white rounded-lg shadow-lg p-6 w-150 relative">
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          
         
            
            {/* Close Button */}
            <button
              onClick={() => setIsOpen(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

         

            {/* Content */}
     <table className="min-w-full bg-white">
  <thead className="bg-gray-100">
    <tr >
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Department Code</th>
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Department Name</th>


    </tr >
  </thead>
   <tbody className="divide-y divide-gray-200" > {depp.map((item) => 
    <tr key={item.id} className="hover:bg-gray-50" onClick={() => {setSelectedCustomer(item);setIsOpen(false);}}>
      <td className="px-6 py-4">{item.DepartmentCode}</td>
      <td className="px-6 py-4">
        {item.DepartmentName}
      </td>
     

    </tr>)}
    </tbody>
    </table>
   

         </div>
          <div className="flex gap-2">
            <button
 onClick={() => {
  
  setIsOpen(false);
}}
              className="mt-3 bg-red-600 hover:bg-red-700 text-white py-2 px-2 rounded-full"
            >
              Close
            </button>

        </div>           
         </div>
         </div>
        
      )}


    
 {/* customers details*/} 
  {isOpenn && (
    <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          
          <div className="bg-white rounded-lg shadow-lg p-6 w-150 relative">
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          
         
            
            {/* Close Button */}
            <button
              onClick={() => setIsOpenn(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

         

            {/* Content */}
     <table className="min-w-full bg-white">
  <thead className="bg-gray-100">
    <tr >
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Category Code</th>
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Category Name</th>


    </tr >
  </thead>
   <tbody className="divide-y divide-gray-200" > {cat.map((item) => 
    <tr key={item.id} className="hover:bg-gray-50" onClick={() => {setSelectedCustomersss(item);setIsOpenn(false);}}>
      <td className="px-6 py-4">{item.CategoryCode}</td>
      <td className="px-6 py-4">
        {item.CategoryName}
      </td>
     

    </tr>)}
    </tbody>
    </table>
   

         </div>
          <div className="flex gap-2">
            <button
 onClick={() => {
  
  setIsOpenn(false);
}}
              className="mt-3 bg-red-600 hover:bg-red-700 text-white py-2 px-2 rounded-full"
            >
              Close
            </button>

        </div>           
         </div>
         </div>
        
      )}


    
 {/* customers details*/} 
  {isOpennn && (
    <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          
          <div className="bg-white rounded-lg shadow-lg p-6 w-150 relative">
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          
         
            
            {/* Close Button */}
            <button
              onClick={() => setIsOpennn(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

         

            {/* Content */}
     <table className="min-w-full bg-white">
  <thead className="bg-gray-100">
    <tr >
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">SubCatagory Code</th>
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">SubCatagory Name</th>


    </tr >
  </thead>
   <tbody className="divide-y divide-gray-200" > {scat.map((item) => 
    <tr key={item.id} className="hover:bg-gray-50" onClick={() => {setSelectedCustomers(item);setIsOpennn(false);}}>
      <td className="px-6 py-4">{item.SubCategoryCode}</td>
      <td className="px-6 py-4">
        {item.SubCategoryName}
      </td>
     

    </tr>)}
    </tbody>
    </table>
   

         </div>
          <div className="flex gap-2">
            <button
 onClick={() => {
  
  setIsOpennn(false);
}}
              className="mt-3 bg-red-600 hover:bg-red-700 text-white py-2 px-2 rounded-full"
            >
              Close
            </button>

        </div>           
         </div>
         </div>
        
      )}



 {isOpennnn && (
    <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          
          <div className="bg-white rounded-lg shadow-lg p-6 w-150 relative">
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          
         
            
            {/* Close Button */}
            <button
              onClick={() => setIsOpennnn(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

         

            {/* Content */}
     <table className="min-w-full bg-white">
  <thead className="bg-gray-100">
    <tr >
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Supplier Code</th>
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Supplier Name</th>


    </tr >
  </thead>
   <tbody className="divide-y divide-gray-200" > {sup.map((item) => 
    <tr key={item.id} className="hover:bg-gray-50" onClick={() => {setSelectedCustomerss(item);setIsOpennnn(false);}}>
      <td className="px-6 py-4">{item.SupplierCode}</td>
      <td className="px-6 py-4">
        {item.SupplierName}
      </td>
     

    </tr>)}
    </tbody>
    </table>
   

         </div>
          <div className="flex gap-2">
            <button
 onClick={() => {
  
  setIsOpennnn(false);
}}
              className="mt-3 bg-red-600 hover:bg-red-700 text-white py-2 px-2 rounded-full"
            >
              Close
            </button>

        </div>           
         </div>
         </div>
        
      )}



    </div>
    </div>
  );
}

export default CreateProduct;