import React, { useState, useRef } from "react";
import axios from "axios";
import { Button } from "@material-tailwind/react";
import { useContext } from "react";
import { AuthContext } from "./SERVER/AuthContext.js";

function Company() {
  const [form, setForm] = useState({
  companycode: "",
        companyname: "",
        address: "",
        mobileno:"",
          username:"",
  
  
  });



 const code = async (value) => {
   
      const res = await fetch(`http://localhost:5000/Companycode?q=${value}`);
      const data = await res.json();
    
    if (data.length > 0) {
      const lastCode =  data[0].CompanyCode || data[0].companycode; // e.g. D001

      // remove letters → get number part
      const numberPart = parseInt(lastCode.replace(/\D/g, ""), 10);

      // +1
      const nextNumber = numberPart + 1;

      // format back with leading zeros
      const nextCode = `${String(nextNumber).padStart(2, "0")}`;

      setForm((prev) => ({
        ...prev,
        companycode: nextCode,
      }));
    }
  }


 const { user } = useContext(AuthContext);
  const [file, setFile] = useState(null);
  const fileInputRef = useRef(null);

  // handle text input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };






  // submit form
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
    
      

      // append image
    

      await axios.post("http://localhost:5000/Company", form);


      // reset form
      setForm({
        companycode: "",
        companyname: "",
        address: "",
        mobileno:"",
        username:"",
  
      });
alert("sucessfully");
      setFile(null);
    } catch (err) {
      console.error(err);
      alert("Error adding product");
    }

  };

  return (
   <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
     <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
      <h2 className="text-2xl font-bold mb-4 text-center">Create Company</h2>
     <form onSubmit={handleSubmit} className="space-y-4">
 {user?.username ? `Welcome, ${user.username}` : "No user logged in"}
        {/* Code + Name */}
      

        {/* Description + Cost */}
         <div className="grid grid-cols-2 gap-4">
       <input
            type="text"
            name="companycode"
            placeholder="Company Code"
            value={form.companycode}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
 <button className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500" onClick={code}>New</button>
         
         </div>
          <input
            type="text"
            name="companyname"
            placeholder="Company Name"
            value={form.companyname}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />

         
       <input
            type="text"
            name="address"
            placeholder="address"
            value={form.address}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />

          <input
            type="text"
            name="mobileno"
            placeholder="mobileno"
            value={form.mobileno}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />

           <button
          type="submit"
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"
        >
          Save
        </button>
      </form>
    </div>
    </div>
  );
}

export default Company;