import { useState } from 'react';
import { useContext } from "react";
import { AuthContext } from "../pos/SERVER/AuthContext.js";
import { useEffect } from "react";
import axios from 'axios';
import { Trash2 } from "lucide-react";
export default function Saleshistory() {
   // 1. Define the active tab state
  const [activeTab, setActiveTab] = useState('pending');
 const { user } = useContext(AuthContext); 
 const [error, setError] = useState("");
   const [loading, setLoading] = useState(false);
  const [showTable, setShowTable] = useState(false);
  const [isOpennnn,setIsOpennnn] = useState(false);
 const [SelectedCustomerss, setSelectedCustomerss] =  useState([]);
   const [scat,setscat] = useState([]);
      const [fromdate,setfromdate] = useState("");
         const [todate,settodate] = useState("");
           const [invoice,setinvoice] = useState([]);

 const [sections, setSections] = useState([]);
 const [cl, setcl] = useState(false);




        
const handleDelete = (id) => {
  setSections((prev) => prev.filter((section) => section.id !== id));
};
     
  // Add item to selected pane
  const handleSelect = (item) => {
  setSections((prev) => {
    const lastSection = prev[prev.length - 1];

    // If no section OR last section already filled → create new section
    if (!lastSection || lastSection.item) {
      return [
        ...prev,
        {
          id: prev.length + 1,
          item: item,
         
        },
        
      ];

    }
     
   
    // Otherwise fill last empty section
    const updated = [...prev];
    updated[updated.length - 1] = {
      ...lastSection,
      item: item,
    };

    return updated;


      
  });

    



  
  };
  useEffect(() => {
  
  })


   const [results, setResults] = useState([]); 
     const [file, setFile] = useState([null]);
      const handleKeyDownsup = (event) => {
    if(event.key === "F12"){
      event.preventDefault();
      setIsOpennnn(true);
      location();
    }
  };
   const location = async (value) => {
        
      const res = await fetch(`http://localhost:5000/location`);
      const data = await res.json();
      setscat(data);
 
   
  }
  const total = sections.reduce((sum, section) => {
  return sum + ((section.item?.SellingPrice || 0) * section.qty);
}, 0);

const discount = sections.reduce((sum, section) => {
  const price = section.item?.SellingPrice || 0;
  const qty = section.qty || 0;
  const disc = section.item?.FixedDiscountPercentage || 0;

  return sum + ((price * qty) * disc / 100);
}, 0);

const subtotal = total - discount;
const totaldiscount = sections.reduce((sum, section) => {
  return sum + (section.item?.FixedDiscountPercentage || 0);
}, 0);

const totalqty = sections.reduce((sum, section) => {
  return sum + (section.qty || 0);
}, 0);

 const inv = async (e) => {
  e.preventDefault();

  try {
    setLoading(true);

    const res = await axios.get(
      "http://localhost:5000/salesreport",
      {
        params: {
          fromdate,
          todate,
          location: SelectedCustomerss.LocationName,
        },
      }
    );

    setinvoice(res.data);
  } catch (err) {
    setError("Failed to load sales report.");
    console.error(err);
  } finally {
    setLoading(false);
  }
};




  return (
    <div className="w-full mx-auto mt-10 p-4">
      {/* Pill Container Grid/Flex */}
      
      {/* Tab Panels Content */}
    {user?.username ? `Welcome, ${user.username}` : "No user logged in"}

     <div className={"mt-6 p-4 bg-white border ${} border-gray-100 rounded-2xl shadow-sm "}>
       
          <div
           
    
            className={`transition-opacity duration-150  'block opacity-100' : 'hidden opacity-0'}`}
          >
           
             <form  className="space-y-4">

        {/* Code + Name */}
         <div className="grid grid-cols-6 gap-4">
       <h3>Location</h3>
        <input
            
            name="location"
                    
        type="text"
            placeholder="Location"
            value={SelectedCustomerss.LocationName}
          //  onChange={handleChange}
            className="w-full border p-2 rounded"
                 onKeyDown={handleKeyDownsup}
            required
          />       


        {/* Description + Cost */}
     
      <h3>From Date</h3>
  <input
            
          
                    
        type="datetime-local"
            placeholder="From Date"
            value={fromdate}
          onChange={(e)=> setfromdate(e.target.value)}
            className="w-full border p-2 rounded"
            required
          />       




   <h3>To Date</h3>
       <input
            
            
                    
        type="datetime-local"
            placeholder="To Date"
            value={todate}
            onChange={(e)=> settodate(e.target.value)}
            className="w-full border p-2 rounded"
            required
          />       

 
      
           <button
         
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"  onClick={inv}
        >
          Search
        </button>
        </div>
      </form>
          </div>
       
          
          
  
          
       
      </div>



      {/* Conditional Table Rendering */}

        <div className="w-full max-w-2xl overflow-hidden rounded-lg shadow-lg border border-gray-200 bg-white mt-4">
          <table className="w-full border-collapse text-left text-sm text-gray-700">
            <thead className="bg-gray-50 text-gray-800">
              <tr>
                <th className="px-6 py-4 font-medium">Inv No</th>
                <th className="px-6 py-4 font-medium">ReferenceNo</th>
                <th className="px-6 py-4 font-medium">Net Amount</th>
                   <th className="px-6 py-4 font-medium">Location</th>
                  
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100 border-t border-gray-100">{invoice.map((row) => (
              
                <tr key={row.id} className="hover:bg-gray-50" onClick={() => {setcl(true);handleSelect(row);}}>
                  <td className="px-6 py-4 font-medium text-gray-900">{row.DocumentNo}</td>
                  <td className="px-6 py-4">{row.ReferenceNo}</td>
                  <td className="px-6 py-4">
                    <span
                      className={`inline-flex items-center gap-1 rounded-full px-2 py-1 text-xs font-semibold ${
                        row.status === 'Active'
                          ? 'bg-green-50 text-green-600'
                          : 'bg-red-50 text-red-600'
                      }`}
                    >
                      {row.NetAmount}
                    </span>
                  </td>
                    <td className="px-6 py-4">{row.LocationName}</td>
                      
                </tr>
          
            ))} </tbody>
          </table>   
        </div>
   
  
 {isOpennnn && (
    <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          
          <div className="bg-white rounded-lg shadow-lg p-6 w-150 relative">
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          
         
            
            {/* Close Button */}
            <button
              onClick={() => setIsOpennnn(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

         

            {/* Content */}
     <table className="min-w-full bg-white">
  <thead className="bg-gray-100">
    <tr >
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Location Code</th>
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Location Name</th>


    </tr >
  </thead>
   <tbody className="divide-y divide-gray-200" > {scat.map((item) => 
    <tr key={item.id} className="hover:bg-gray-50" onClick={() => {setSelectedCustomerss(item);setIsOpennnn(false);}}>
      <td className="px-6 py-4">{item.LocationCode}</td>
      <td className="px-6 py-4">
        {item.LocationName}
      </td>
     

    </tr>)}
    </tbody>
    </table>
   

         </div>
          <div className="flex gap-2">
            <button
 onClick={() => {
  
  setIsOpennnn(false);
}}
              className="mt-3 bg-red-600 hover:bg-red-700 text-white py-2 px-2 rounded-full"
            >
              Close
            </button>

        </div>           
         </div>
         </div>
        
      )}





  
  {/* CUSTOMER BOX */}
  
  
  {cl && ( <div className="fixed right-1 top-0 h-screen w-[370px] bg-white rounded-3xl shadow-2xl px-4 flex flex-col">
    {/* HEADER */}
    <div className="relative border-b pb-2 pt-2 mb-3">
    
    <h2 className="text-xl font-bold ">
      POS Cart
    </h2>
    <button
  
    onClick={() => setcl(false)}
    className="absolute top-0 right-0 bg-blue-600 hover:bg-blue-700 text-white px-3 py-1.5 rounded-full text-sm"
  >
    Close
  </button>
  
    </div>
   
   <ul className="divide-y">
      <li          
         className="grid grid-cols-[2fr_1fr_1fr_1fr_0.5fr] gap-2 px-2 py-2 bg-gray-100 border-b text-xs font-semibold text-gray-600"
            >
               <span className="text-sm font-medium">
                ProductCode
              </span>
              <span className="text-sm font-medium">
                Product
              </span>
               <span className="text-sm font-medium">
                Discount
              </span>
                <span className="text-sm font-medium">
                Qty
              </span>
                <span className="text-sm font-medium">
                Price
              </span>
            </li>
   </ul>
    {/* ITEMS */}
    <div className="flex-1 overflow-y-auto px-2 scrollbar-thin scrollbar-thumb-gray-400 scrollbar-track-gray-100">
      {sections.length === 0 ? (
        <p className="text-gray-400 text-center mt-10">
          No items added
        </p>
      ) : (
        <ul className="divide-y">
          {sections.map((section) => (
            <li
              key={section.id}
              className="flex justify-between items-center py-3 px-2 hover:bg-gray-100"
            >
               <span className="text-sm font-medium">
                {section.item?.ProductCode }
              </span>
  
              <span className="text-sm font-medium">
                {section.item?.ProductName }
              </span>
  
                <span className="text-sm font-medium">
                {section.item?.FixedDiscountPercentage + '%'}
              </span>
  
               <span className="text-sm font-medium">
                {section.item.qty}
              </span>
  
              <span className="text-sm font-medium">
                {section.item?.SellingPrice}
              </span>
  
              <Trash2
                size={18}
                className="text-red-500 cursor-pointer hover:text-red-700"
                onClick={() => handleDelete(section.id)}
              />
            </li>
          ))}
        </ul>
      )}
  
  
  
      
  
  
      
    </div>
  
    {/* FOOTER SUMMARY */}
    <div className="border-t pt-3 mt-3 space-y-2">
  
    
    
    <div className="flex justify-between text-sm font-semibold">
      <span>Total Items</span>
      <span>{sections.length}</span>
    </div>

    <div className="flex justify-between text-sm font-semibold">
      <span>Total Qty</span>
      <span>{totalqty}</span>
    </div>

     
  
    </div>
    <div className="border-t pt-3 mt-3 space-y-2">
  
      <div className="flex justify-between text-sm font-semibold">
      <span>Discount Percentage</span>
      <span>{totaldiscount + '%'}</span>
    </div>
 <div className="flex justify-between text-sm font-semibold">
      <span>Discount</span>
      <span>{discount}</span>
    </div>
    <div className="flex justify-between text-sm font-semibold">
      <span>Total</span>
      <span>{subtotal}</span>
    </div>
  
  
  </div>
      
  </div>)}




    </div> 

    
  );

  
  
  

}

