import React, { useState, useRef } from "react";
import axios from "axios";

function Customer() {
  const [form, setForm] = useState({
   code: "",
        customername: "",
        address: "",
        mobileno: "",
        email: "",
        dateofbirth: "",
        cretditlimit: "",
        discountlimit: "",
        
  });

  const [file, setFile] = useState(null);
  const fileInputRef = useRef(null);
  const [activeIndex, setActiveIndex] = useState(""); 
     const [results, setResults] = useState([]); 
      const handleSearchs = async (value) => {
   
      const res = await fetch(`http://localhost:5000/CustomerCode?q=${value}`);
      const data = await res.json();
    
    if (data.length > 0) {
      const lastCode =  data[0].CustomerCode; // e.g. D001

      // remove letters → get number part
      const numberPart = parseInt(lastCode.replace(/\D/g, ""), 10);

      // +1
      const nextNumber = numberPart +1;
alert(nextNumber)
      // format back with leading zeros
     // const nextCode = `${String(nextNumber).padStart(4, "0")}`;

      setForm((prev) => ({
        ...prev,
        code: nextNumber,
      }));
    }
    setActiveIndex(0);   
   
    
    
  };

  // handle text input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // submit form
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
     

      // append all text fields
   
      await axios.post("http://localhost:5000/customer", form
      
      );

      alert("Product added!");

      // reset form
      setForm({
        code: "",
        customername: "",
        address: "",
        mobileno: "",
        email: "",
        dateofbirth: "",
        cretditlimit: "",
        discountlimit: "",
        
      });

      setFile(null);
    } catch (err) {
      console.error(err);
      alert("Error adding product");
    }
  };

  return (
   <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
     <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
      <h2 className="text-2xl font-bold mb-4 text-center">Create Customer</h2>

      <form onSubmit={handleSubmit} className="space-y-4">

        {/* Code + Name */}
        <div className="grid grid-cols-2 gap-4">
      
          <input
            type="text"
            name="code"
            placeholder="code"
            value={form.code}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
 <button type="button" className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500" onClick={handleSearchs}>New</button>
      
      </div>
        <div className="grid grid-cols-2 gap-4">
       
          <input
            type="text"
            name="customername"
            placeholder="Product Name"
            value={form.customername}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
      

        {/* Description + Cost */}
       
          <input
            type="text"
            name="address"
            placeholder="address"
            value={form.address}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
  </div>
    <div className="grid grid-cols-2 gap-4">
       
          <input
            type="number"
            name="mobileno"
            placeholder="Cost Price"
            value={form.mobileno}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
      

      
          <input
            type="text"
            name="email"
            placeholder="Selling Price"
            value={form.email}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>
      <div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="dateofbirth"
            placeholder="dateofbirth"
            value={form.dateofbirth}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
       


          <input
            type="number"
            name="cretditlimit"
            placeholder="cretditlimit"
            value={form.cretditlimit}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
 </div>
 <div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="discountlimit"
            placeholder="discountlimit"
            value={form.discountlimit}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
       </div>
        {/* Submit */}
        <button
          type="submit"
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"
        >
          Save Product
        </button>
      </form>
    </div>
    </div>
  );
}

export default Customer;