import React, { useState, useRef,useEffect } from "react";
import axios from "axios";

function Employee() {
  const [isOpen,setIsOpen] = useState(false);
   const [isOpenn,setIsOpenn] = useState(false);
    const [isOpennn,setIsOpennn] = useState(false);
        const [isOpennnn,setIsOpennnn] = useState(false);
  const [SelectedCustomer,setSelectedCustomer] = useState([]);
  const [results,setResults]= useState([]);
  const [resultss,setResultss]= useState([]);
  const [resultsss,setResultsss]= useState([]);
    const [resultssss,setResultssss]= useState([]);
  const[tx,istx]=useState(0);
  const [act,isact]=useState(0);
  const [sup,setsup] = useState([]);
  const [depp,setdepp] = useState([]);
   const [cat,setcat] = useState([]);
     const [scat,setscat] = useState([]); 
  const [form, setForm] = useState({
    code: "",
        employeename: "",
        title: "",
        gender: "",
        referenceno: "",
        designation: "",
        address: "",
        mobile: "",
        location: "",
        maximumdiscount: "",
        minimumdiscount: "",
     creditlimit: "",
        purchaselimit: "",
        isactive:"",
  });

 
   
  
 const Location = async () => {
        
      const res = await fetch(`http://localhost:5000/Location`);
      const data = await res.json();
      setdepp(data);
 
   
  }





  const handleKeyDown = (event) => {
    if(event.key === "F12"){
      event.preventDefault();
      setIsOpen(true);
      Location();
    }
  };

 
  const [file, setFile] = useState(null);
  const fileInputRef = useRef(null);

  // handle text input
  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  // submit form
  const handleSubmit = async (e) => {
 

    try {
         const payload = {
      code: form.code,
      employeename:form.employeename,
      title: Number(form.title),
      gender: Number(form.gender),
      referenceno:form.referenceno,
      designation:form.designation,
      address:form.address,
      mobile:form.mobile,
      location: Number(form.location),
      maximumdiscount: Number(form.maximumdiscount),
      minimumdiscount: Number(form.minimumdiscount),
      creditlimit: Number(form.creditlimit),
      purchaselimit: Number(form.purchaselimit),
      isactive: form.isactive === "1",
    };
    

      await axios.post("http://localhost:5000/employee", payload );

      alert("Product added!");

      // reset form
      setForm({
        code: "",
        employeename: "",
        title: "",
        gender: "",
        referenceno: "",
        designation: "",
        address: "",
        mobile: "",
        location: "",
        maximumdiscount: "",
        minimumdiscount: "",
     creditlimit: "",
        purchaselimit: "",
           isactive:"",
      });

      setFile(null);
    } catch (err) {
      console.error(err);
      alert("Error adding product");
    }
  

  };



  const code = async (value) => {
   
      const res = await fetch(`http://localhost:5000/employeecode?q=${value}`);
      const data = await res.json();
    
    if (data.length > 0) {
      const lastCode =  data[0].EmployeeCode || data[0].Employeecode; // e.g. D001

      // remove letters → get number part
      const numberPart = parseInt(lastCode.replace(/\D/g, ""), 10);

      // +1
      const nextNumber = numberPart + 1;

      // format back with leading zeros
      const nextCode = `${String(nextNumber).padStart(4, "0")}`;

      setForm((prev) => ({
        ...prev,
        code: nextCode,
      }));
    }
   
   
    
    
  };

  return (
   <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
     <div className="w-full max-w-2xl bg-white p-6 rounded-xl shadow-2xl border border-gray-200">
      <h2 className="text-2xl font-bold mb-4 text-center">Employee</h2>

      <form onSubmit={handleSubmit} className="space-y-4">

        {/* Code + Name */}
        <div className="grid grid-cols-2 gap-4">
      
          <input
            type="text"
            name="code"
            placeholder="Employee Code"
            value={form.code}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />

   <button type="button" className=" bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500" onClick={code}>New</button>
</div>
      <div className="grid grid-cols-2 gap-4">
          <input
            type="text"
            name="employeename"
            placeholder="Employee Name"
            value={form.employeename}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        

  
    
          <select
  name="title"
  value={form.title}
  onChange={handleChange}
  className="w-full border p-2 rounded"
  required
>  <option value="">Title</option>
  <option value="1">Mr</option>

  <option value="2">Ms</option>
</select>
</div>
      <div className="grid grid-cols-2 gap-4">
         
    
          <select
  name="gender"
  value={form.gender}
  onChange={handleChange}
  className="w-full border p-2 rounded"
  required
>  <option value="">Gender</option>
  <option value="1">Male</option>

  <option value="2">Female</option>
</select>
        

        {/* Selling + Discount */}
  
          <input
            type="text"
            name="referenceno"
            placeholder="Reference No"
            value={form.referenceno}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>
      <div className="grid grid-cols-2 gap-4">
          <input
            type="text"
            name="designation"
            placeholder="Designation"
            value={form.designation}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        

          <input
            type="text"
            name="address"
            placeholder="Address"
            value={form.address}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
</div>
      <div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="mobile"
            placeholder="Mobile"
            value={form.mobile}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        

        {/* Discount + Retail */}
      
          <input
            type="text"
            name="location"
            placeholder="Location"
            value={form.location}
            onChange={handleChange}
             onKeyDown={handleKeyDown}
            className="w-full border p-2 rounded"
            required
          />
</div>


<div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="maximumdiscount"
            placeholder="Maximum Discount"
            value={form.maximumdiscount}
            onChange={handleChange}
            
            className="w-full border p-2 rounded"
            required
          />
        

     
          <input
            type="number"
            name="minimumdiscount"
            placeholder="Minimum Discount"
            value={form.minimumdiscount}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
        
</div>




      <div className="grid grid-cols-2 gap-4">
          <input
            type="number"
            name="creditlimit"
            placeholder="Credit Limit"
            value={form.creditlimit}
            onChange={handleChange}
            className="w-full border p-2 rounded"
            required
          />
  

          <input
            type="number"
            name="purchaselimit"
            placeholder="Purchase Limit"
            value={form.purchaselimit}
            onChange={handleChange}
            
            className="w-full border p-2 rounded"
            required
            
          />
          
</div>
    


      <div className="grid grid-cols-2 gap-4">
          <label
         
          className="flex items-center gap-2 cursor-pointer"
        >
<div className="grid grid-cols-2 gap-4">

  <div>
    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="isactive"
        value="1"
        checked={form.isactive === "1"}
        onChange={handleChange}
      />
      Active
    </label>

    <label className="flex items-center gap-2">
      <input
        type="radio"
        name="isactive"
        value="0"
        checked={form.isactive === "0"}
        onChange={handleChange}
      />
      Inactive
    </label>
  </div>


</div>
        </label>
  
        
        {/* Submit */}
        <button
          type="submit"
          className="w-full bg-indigo-600 text-white py-2 rounded hover:bg-indigo-500"
        >
          Save Employee
        </button>
        </div>
      </form>
      
 {/* customers details*/} 
  {isOpen && (
    <div className="fixed inset-0 flex items-center justify-center bg-black bg-opacity-50">
          
          <div className="bg-white rounded-lg shadow-lg p-6 w-150 relative">
        <div className="overflow-x-auto rounded-lg border border-gray-200">
          
         
            
            {/* Close Button */}
            <button
              onClick={() => setIsOpen(false)}
              className="absolute top-2 right-2 text-gray-500 hover:text-black"
            >
              ✕
            </button>

         

            {/* Content */}
     <table className="min-w-full bg-white">
  <thead className="bg-gray-100">
    <tr >
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Location Code</th>
      <th className="px-6 py-3 text-center text-sm font-semibold text-gray-500">Location Name</th>


    </tr >
  </thead>
   <tbody className="divide-y divide-gray-200" > {depp.map((item) => 
    <tr key={item.id} className="hover:bg-gray-50" onClick={() => {setSelectedCustomer(item);setIsOpen(false);}}>
      <td className="px-6 py-4">{item.LocationCode}</td>
      <td className="px-6 py-4">
        {item.LocationName}
      </td>
     

    </tr>)}
    </tbody>
    </table>
   

         </div>
          <div className="flex gap-2">
            <button
 onClick={() => {
  
  setIsOpen(false);
}}
              className="mt-3 bg-red-600 hover:bg-red-700 text-white py-2 px-2 rounded-full"
            >
              Close
            </button>

        </div>           
         </div>
         </div>
        
      )}


    </div>
    </div>
  );
}

export default Employee;